els.mentorMeetingReportForm.addEventListener("submit", async (event) => {
  event.preventDefault();
  const form = event.currentTarget;
  const caseRecord = mentorAssignments().find((assignment) => assignment.id === form.dataset.caseId);
  const meeting = allInteractions().find((item) => item.id === form.dataset.interactionId && item.kind === "meeting");
  const existingMeeting = meeting?.sourceType === "case_meeting"
    ? caseMeetings.find((item) => item.id === meeting.sourceId)
    : null;
  if (!caseRecord || caseRecord.status === "closed" || !meeting || !existingMeeting) {
    showFeedback("Mötet kunde inte återrapporteras. Läs in sidan igen.");
    return;
  }
  if (mentorReportForMeeting(caseRecord, meeting)) {
    mentorMeetingReportModal?.hide();
    showFeedback("Mötet har redan en rapport.");
    return;
  }
  const formData = new FormData(form);
  const reportId = crypto.randomUUID();
  const actor = currentActorId();
  const occurredOn = calendarDateKey(new Date(meeting.startsAt));
  const durationMinutes = Number(formData.get("durationMinutes"));
  const outcome = String(formData.get("outcome") || "completed");
  const summary = String(formData.get("summary") || "").trim();
  const nextContactOn = String(formData.get("nextContactOn") || "") || null;
  const retainedNextStep = meeting.nextStep && !/återrapportera/i.test(meeting.nextStep)
    ? meeting.nextStep
    : "Fortsätt enligt uppdragsplanen.";
  els.mentorMeetingReportSubmitButton.disabled = true;
  els.mentorMeetingReportSubmitButton.textContent = "Skickar...";
  try {
    const meetingResult = await registerCaseMeetingCommand({
      caseRecord,
      existing: existingMeeting,
      meetingType: existingMeeting.meetingType || "follow_up",
      meetingStatus: outcome,
      confirmationStatus: meeting.confirmationStatus,
      occurredAt: meeting.startsAt,
      endsAt: new Date(new Date(meeting.startsAt).getTime() + durationMinutes * 60 * 1000).toISOString(),
      mode: meeting.mode,
      activityId: meeting.activityId,
      title: meeting.title,
      location: meeting.location,
      invitationText: meeting.invitationText,
      communicationHistory: meeting.communicationHistory,
      participants: meeting.participants,
      reminder: { enabled: false, offsetMinutes: meeting.reminder?.offsetMinutes || 1440 },
      organizerId: meeting.organizerId,
      summary,
      nextStep: nextContactOn ? `Nästa kontakt planerad ${formatDate(nextContactOn)}.` : retainedNextStep,
      rescheduledFromInteractionId: meeting.rescheduledFromInteractionId
    });
    await executeCaseCommand({
      commandType: "register_mentor_self_report",
      caseId: caseRecord.id,
      expectedVersion: null,
      payload: { reportId, meetingId: meetingResult.meetingId, interactionId: meeting.id, occurredOn },
      additionalStores: [MENTOR_REPORTS_STORE],
      mutate: ({ currentCase, now, put, event: recordEvent }) => {
        put(MENTOR_REPORTS_STORE, {
          id: reportId,
          tenantId: DEFAULT_TENANT_ID,
          caseId: currentCase.id,
          meetingId: meetingResult.meetingId,
          interactionId: meeting.id,
          mentorId: currentCase.mentorId,
          occurredOn,
          durationMinutes,
          mode: meeting.mode || "physical",
          outcome,
          nextContactOn,
          summary,
          needsHandlerSupport: formData.get("needsHandlerSupport") === "on",
          reportedByMentorId: currentCase.mentorId,
          recordedBy: actor,
          createdAt: now,
          createdBy: actor
        });
        const updated = { ...currentCase, version: currentCase.version + 1, updatedAt: now, updatedBy: actor };
        put(CASES_STORE, updated);
        recordEvent("mentor_self_report_registered", "mentor_report", reportId, `Mentorn återrapporterade mötet ${occurredOn}`);
        return { caseId: currentCase.id, version: updated.version };
      }
    });
    mentorMeetingReportModal.hide();
    markSaved();
    showFeedback("Mötet har återrapporterats till handläggaren.");
    await refresh();
  } catch (error) {
    console.error("Kunde inte återrapportera mötet", error);
    showFeedback(error?.message || "Mötet kunde inte återrapporteras.");
  } finally {
    els.mentorMeetingReportSubmitButton.disabled = false;
    els.mentorMeetingReportSubmitButton.textContent = "Skicka rapport";
  }
});

els.mentorReportDetailModal.addEventListener("submit", async (event) => {
  const form = event.target.closest("#mentorReportSupplementForm");
  if (!form) return;
  event.preventDefault();
  const report = mentorReports.find((item) => item.id === form.dataset.reportId);
  const caseRecord = cases.find((item) => item.id === report?.caseId);
  if (!canSupplementMentorReport(report, caseRecord)) {
    showFeedback("Rapporten kan inte kompletteras i det här läget.");
    return;
  }
  const textarea = form.querySelector('[name="text"]');
  textarea.setCustomValidity("");
  const actor = currentActorId();
  const supplementId = crypto.randomUUID();
  try {
    await executeCaseCommand({
      commandType: "add_mentor_report_supplement",
      caseId: caseRecord.id,
      expectedVersion: caseRecord.version,
      payload: { reportId: report.id, supplementId },
      additionalStores: [MENTOR_REPORTS_STORE],
      mutate: ({ currentCase, now, put, event: recordEvent }) => {
        const updatedReport = appendMentorReportSupplement(report, {
          id: supplementId,
          text: textarea.value,
          createdAt: now,
          createdBy: actor
        });
        put(MENTOR_REPORTS_STORE, updatedReport);
        const updatedCase = { ...currentCase, version: currentCase.version + 1, updatedAt: now, updatedBy: actor };
        put(CASES_STORE, updatedCase);
        recordEvent("mentor_report_supplement_added", "mentor_report", report.id, "En komplettering lades till i mentorrapporten");
        return { caseId: currentCase.id, version: updatedCase.version };
      }
    });
  } catch (error) {
    textarea.setCustomValidity(error.message);
    textarea.reportValidity();
    return;
  }
  markSaved();
  await refresh();
  renderMentorReportDetail(mentorReports.find((item) => item.id === selectedMentorReportId));
  showFeedback("Kompletteringen har lagts till utan att originalrapporten ändrades.");
});

els.publicPortalView.addEventListener("click", (event) => {
  if (event.target.closest("[data-new-public-support]")) {
    lastPublicSupportRequestId = "";
    renderPublicSupport();
    return;
  }
  if (event.target.closest("[data-edit-public-mentor-application]")) {
    publicMentorApplicationEditing = true;
    publicMentorApplicationStep = 1;
    renderPublicMentorApplication();
    return;
  }
  const form = event.target.closest("#publicMentorApplicationForm");
  if (!form) return;
  const previous = currentPublicMentorApplication();
  const persistDraft = async () => {
    const application = publicMentorApplicationFromForm(form, previous);
    await saveMentorApplication(application);
    localStorage.setItem(PUBLIC_MENTOR_APPLICATION_KEY, application.id);
    mentorApplications = [application, ...mentorApplications.filter((item) => item.id !== application.id)];
    return application;
  };
  if (event.target.closest("[data-public-mentor-back]")) {
    publicMentorApplicationStep -= 1;
    updatePublicMentorApplicationStep();
    return;
  }
  if (event.target.closest("[data-public-mentor-next]")) {
    if (!validatePublicMentorApplicationStep(form, publicMentorApplicationStep)) return;
    persistDraft().then(() => {
      publicMentorApplicationStep += 1;
      updatePublicMentorApplicationStep();
    }).catch((error) => showFeedback(error.message));
    return;
  }
  if (event.target.closest("[data-public-mentor-save]")) {
    persistDraft().then(() => {
      markSaved();
      showFeedback("Utkastet har sparats i den här webbläsaren.");
    }).catch((error) => showFeedback(error.message));
  }
});

els.publicPortalView.addEventListener("change", (event) => {
  const supportAreaInput = event.target.closest('input[name="mentorSupportArea"]');
  if (!supportAreaInput) return;
  const row = supportAreaInput.closest("[data-public-mentor-support-row]");
  const details = row?.querySelector(".public-mentor-support-details");
  if (details) details.hidden = !supportAreaInput.checked;
});

els.publicPortalView.addEventListener("submit", async (event) => {
  const mentorForm = event.target.closest("#publicMentorApplicationForm");
  if (mentorForm) {
    event.preventDefault();
    for (const step of [1, 2, 3]) {
      if (!validatePublicMentorApplicationStep(mentorForm, step)) {
        publicMentorApplicationStep = step;
        updatePublicMentorApplicationStep();
        return;
      }
    }
    const consent = mentorForm.querySelector('input[name="consent"]');
    if (!consent.checked) {
      const error = mentorForm.querySelector("#publicMentorApplicationError");
      error.textContent = "Godkänn att kommunen får kontakta dig innan du skickar intresseanmälan.";
      error.hidden = false;
      consent.focus();
      return;
    }
    const previous = currentPublicMentorApplication();
    const draft = publicMentorApplicationFromForm(mentorForm, previous);
    try {
      const submitted = submitMentorApplication(draft, { now: new Date().toISOString(), actorId: "public-applicant" });
      await saveMentorApplication(submitted);
      localStorage.setItem(PUBLIC_MENTOR_APPLICATION_KEY, submitted.id);
      await sendMentorApplicationMessage(submitted, {
        subject: "Vi har tagit emot din intresseanmälan",
        body: `Hej ${submitted.name}! Vi har registrerat din intresseanmälan med referens ${submitted.reference}. Kommunen går igenom uppgifterna och kontaktar dig. Detta meddelande har registrerats i prototypens demoleverantör och har inte skickats externt.`,
        actorId: "system"
      });
      publicMentorApplicationEditing = false;
      publicMentorApplicationStep = 1;
      markSaved();
      await refresh();
      showFeedback("Intresseanmälan har registrerats i prototypen.");
    } catch (error) {
      const feedback = mentorForm.querySelector("#publicMentorApplicationError");
      feedback.textContent = error.message;
      feedback.hidden = false;
    }
    return;
  }
  const form = event.target.closest("#publicSupportForm");
  if (!form) return;
  event.preventDefault();
  if (!form.reportValidity()) return;
  const formData = new FormData(form);
  const now = new Date().toISOString();
  const id = crypto.randomUUID();
  const request = {
    id,
    tenantId: DEFAULT_TENANT_ID,
    reference: `FMP-${now.slice(0, 4)}-${id.slice(0, 6).toUpperCase()}`,
    name: String(formData.get("name") || "").trim(),
    contactMethod: String(formData.get("contactMethod") || "phone"),
    contact: String(formData.get("contact") || "").trim(),
    area: String(formData.get("area") || "").trim(),
    description: String(formData.get("description") || "").trim(),
    supportAreaIds: normalizeSupportAreaIds(formData.getAll("publicSupportArea")),
    supportAreaUncertain: formData.get("supportAreaUncertain") === "yes",
    availability: String(formData.get("availability") || "").trim(),
    status: "received",
    createdAt: now,
    source: "public_portal"
  };
  await savePublicSupportRequest(request);
  lastPublicSupportRequestId = id;
  markSaved();
  await refresh();
});

els.mentorApplicationQueueToggle.addEventListener("click", () => {
  const hidden = !els.mentorApplicationQueueContent.hidden;
  els.mentorApplicationQueueContent.hidden = hidden;
  els.mentorApplicationQueueToggle.textContent = hidden ? "Visa" : "Dölj";
  els.mentorApplicationQueueToggle.setAttribute("aria-expanded", String(!hidden));
});

els.mentorApplicationQueuePanel.addEventListener("click", async (event) => {
  const openButton = event.target.closest("[data-open-mentor-application]");
  if (openButton) {
    selectedMentorApplicationId = openButton.dataset.openMentorApplication;
    renderMentorApplicationQueue();
    els.mentorApplicationDetailPanel.scrollIntoView({ block: "nearest" });
    return;
  }
  if (event.target.closest("[data-close-mentor-application]")) {
    selectedMentorApplicationId = "";
    renderMentorApplicationQueue();
    return;
  }
  const application = mentorApplications.find((item) => item.id === selectedMentorApplicationId);
  if (!application) return;
  const linkButton = event.target.closest("[data-link-mentor-application]");
  if (linkButton) {
    const candidate = candidates.find((item) => item.id === linkButton.dataset.linkMentorApplication);
    if (!candidate) return;
    await linkMentorApplicationToCandidate(application, candidate);
    selectedMentorApplicationId = "";
    markSaved();
    await refresh();
    window.location.hash = `#/mentor/${candidate.id}`;
    showFeedback("Intresseanmälan har kopplats till den befintliga mentorn.");
    return;
  }
  if (event.target.closest("[data-request-mentor-completion]")) {
    const now = new Date().toISOString();
    const updated = normalizeMentorApplication({
      ...application,
      status: "needs_completion",
      updatedAt: now,
      updatedBy: currentActorId(),
      version: application.version + 1,
      history: [...application.history, { eventType: "completion_requested", occurredAt: now, actorId: currentActorId(), message: "Kommunen begärde en komplettering av intresseanmälan." }]
    });
    await saveMentorApplication(updated);
    await sendMentorApplicationMessage(updated, {
      subject: "Komplettera din intresseanmälan",
      body: `Hej ${updated.name}! Kommunen behöver att du ser över och kompletterar din intresseanmälan ${updated.reference}. Öppna Min ansökan i samma webbläsare för att ändra uppgifterna. Detta är ett registrerat demomeddelande och har inte skickats externt.`,
      actorId: currentActorId()
    });
    markSaved();
    await refresh();
    showFeedback("Begäran om komplettering har registrerats via demoleverantören.");
    return;
  }
  if (event.target.closest("[data-convert-mentor-application]")) {
    try {
      const candidate = await convertMentorApplicationToCandidate(application);
      selectedMentorApplicationId = "";
      markSaved();
      await refresh();
      window.location.hash = `#/mentor/${candidate.id}`;
      showFeedback("Mentorn har skapats och godkännandeflödet har startats.");
    } catch (error) {
      console.error("Kunde inte ta emot mentoransökan", error);
      showFeedback(error.message || "Intresseanmälan kunde inte tas emot.");
    }
  }
});

function populateInteractionSelect(select, records, label, selectedId = "") {
  select.innerHTML = `<option value="">Ingen</option>`;
  for (const record of records) {
    const option = document.createElement("option");
    option.value = record.id;
    option.textContent = label(record);
    select.append(option);
  }
  select.value = selectedId || "";
}

function suggestedMeetingTitle(caseRecord) {
  if (!caseRecord) return "Möte";
  if (caseRecord.caseTypeId === "mentor-certification") return "Intervju inför godkännande";
  if (caseRecord.caseTypeId === "matching") return "Första mötet mellan förälder och mentor";
  if (caseRecord.caseTypeId === "mentor-assignment") return "Uppföljning av mentoruppdrag";
  return `Möte: ${caseRecord.title}`.slice(0, 100);
}

function selectedInteractionOutcomeStatus() {
  return els.interactionForm.querySelector('input[name="interactionOutcomeStatus"]:checked')?.value || "completed";
}

function clearInteractionValidity() {
  els.interactionStartInput.setCustomValidity("");
  els.interactionEndInput.setCustomValidity("");
  els.interactionParentInput.setCustomValidity("");
  els.interactionSummaryInput.setCustomValidity("");
}

function interactionOutcomeActionLabel(status) {
  if (status === "cancelled") return "Markera som inställt";
  if (status === "no_show") return "Markera som uteblivet";
  return "Markera som genomfört";
}

const INTERACTION_COMMUNICATION_LABELS = {
  time_request: "Förfrågan om dag och tid",
  time_response: "Svar på tidsförfrågan",
  time_confirmed: "Godkänd tid",
  invitation_sent: "Kallelse skickad",
  reminder_sent: "Påminnelse skickad",
  rescheduled: "Ombokning",
  cancelled: "Avbokning",
  other: "Övrigt"
};

function interactionDraftItems(key) {
  try {
    const items = JSON.parse(els.interactionForm.dataset[key] || "[]");
    return Array.isArray(items) ? items : [];
  } catch {
    return [];
  }
}

function setInteractionDraftItems(key, items) {
  els.interactionForm.dataset[key] = JSON.stringify(items);
}

function externalParticipantsFromForm() {
  return interactionDraftItems("externalParticipants");
}

function renderExternalParticipants() {
  const participants = externalParticipantsFromForm();
  els.interactionExternalParticipantCount.textContent = `${participants.length} ${participants.length === 1 ? "tillagd" : "tillagda"}`;
  els.interactionExternalParticipantList.innerHTML = participants.length
    ? participants.map((participant) => {
      const contact = [participant.phone, participant.email].filter(Boolean).join(" · ") || "Ingen kontaktuppgift";
      return `<div class="interaction-external-participant"><div><strong>${escapeHtml(participant.displayName)}</strong><span>${escapeHtml(participant.roleLabel || "Roll ej angiven")}</span><small>${escapeHtml(contact)}</small></div><button type="button" class="btn btn-link btn-sm" data-remove-external-participant="${escapeHtml(participant.id)}">Ta bort</button></div>`;
    }).join("")
    : '<p class="small text-secondary mb-0">Inga övriga deltagare har lagts till.</p>';
}

function communicationHistoryFromForm() {
  return interactionDraftItems("communicationHistory").map(({ pending, ...item }) => item);
}

function renderInteractionCommunicationHistory() {
  const history = interactionDraftItems("communicationHistory")
    .sort((left, right) => new Date(left.occurredAt) - new Date(right.occurredAt));
  els.interactionCommunicationCount.textContent = history.length + communicationsForInteraction(els.interactionForm.dataset.interactionId).length;
  els.interactionCommunicationList.innerHTML = history.length
    ? history.map((item) => `<article class="interaction-communication-item${item.pending ? " is-pending" : ""}"><time datetime="${escapeHtml(item.occurredAt)}">${escapeHtml(formatDateTime(item.occurredAt))}</time><div><strong>${escapeHtml(INTERACTION_COMMUNICATION_LABELS[item.type] || INTERACTION_COMMUNICATION_LABELS.other)}</strong><p>${escapeHtml(item.comment)}</p><small>${escapeHtml(handlerNameById(item.createdBy) || item.createdBy || "System")}${item.pending ? " · sparas med mötet" : ""}</small></div>${item.pending ? `<button type="button" class="btn btn-link btn-sm" data-remove-communication="${escapeHtml(item.id)}">Ta bort</button>` : ""}</article>`).join("")
    : '<p class="small text-secondary mb-0">Ingen kommunikation har registrerats ännu.</p>';
}

function updateInteractionFormState({ applyCaseSuggestions = false } = {}) {
  clearInteractionValidity();
  const scheduled = els.interactionScheduledInput.checked;
  const editing = Boolean(els.interactionForm.dataset.interactionId);
  const originalStatus = els.interactionForm.dataset.originalStatus || "";
  const interactionKind = scheduled ? "meeting" : els.interactionKindInput.value;
  const editingScheduledMeeting = editing && originalStatus === "scheduled";
  const existingInteraction = allInteractions().find((item) => item.id === els.interactionForm.dataset.interactionId);
  const editingPastDueMeeting = editingScheduledMeeting && interactionTimingState(existingInteraction || {}) === "past_due";
  els.interactionIntentSwitch.hidden = editing && !editingScheduledMeeting;
  els.interactionIntentLegend.textContent = editingPastDueMeeting ? "Mötet har passerat. Vad hände?" : editingScheduledMeeting ? "Vad vill du göra?" : "Vad vill du registrera?";
  els.interactionScheduledLabel.textContent = editingScheduledMeeting ? "Ändra bokningen" : "Planerat möte";
  els.interactionCompletedLabel.textContent = editingScheduledMeeting ? "Registrera utfall" : "Genomförd kontakt";
  els.interactionCaseInput.options[0].textContent = scheduled ? "Fristående möte" : "Fristående kontakt";
  els.interactionTitle.textContent = editingScheduledMeeting
    ? scheduled ? editingPastDueMeeting ? "Passerat möte, utfall saknas" : "Bokat möte" : "Registrera mötesutfall"
    : editing && interactionKind === "meeting"
      ? `${INTERACTION_STATUS_LABELS[originalStatus] || "Öppna"} möte`
      : editing
        ? "Genomförd kontakt"
        : scheduled
          ? "Boka möte"
          : "Registrera genomförd kontakt";
  els.interactionPlanningFields.hidden = !scheduled;
  els.interactionInvitationDetails.hidden = !scheduled;
  els.interactionCommunicationDetails.hidden = interactionKind !== "meeting";
  els.interactionResponseSection.hidden = !scheduled || !editing;
  els.interactionOutcomeFields.hidden = scheduled;
  els.interactionEndInput.required = scheduled;
  els.interactionSummaryInput.required = !scheduled;
  els.interactionSummaryRequired.hidden = scheduled;
  els.interactionKindInput.disabled = scheduled;
  if (scheduled) els.interactionKindInput.value = "meeting";
  const completedMeeting = !scheduled && els.interactionKindInput.value === "meeting" && selectedInteractionOutcomeStatus() === "completed";
  els.interactionMeetingOutcomeSection.hidden = scheduled || els.interactionKindInput.value !== "meeting";
  els.interactionAttendanceSection.hidden = !completedMeeting;
  els.interactionSubmitButton.textContent = editingScheduledMeeting && !scheduled
    ? interactionOutcomeActionLabel(selectedInteractionOutcomeStatus())
    : editingScheduledMeeting
      ? "Spara bokning"
      : editing
        ? "Spara rättelse"
        : scheduled
          ? "Skapa bokning"
          : "Spara kontakt";
  els.interactionCopyInvitationButton.disabled = !els.interactionInvitationInput.value.trim();
  const reminder = normalizeMeetingReminder({
    enabled: scheduled && els.interactionReminderEnabledInput.checked,
    offsetMinutes: els.interactionReminderOffsetInput.value
  });
  els.interactionReminderOptions.hidden = !reminder.enabled;
  els.interactionReminderOffsetInput.disabled = !reminder.enabled;
  if (reminder.enabled) {
    const startsAt = new Date(els.interactionStartInput.value).getTime();
    const triggerAt = startsAt - reminder.offsetMinutes * 60 * 1000;
    const contactCount = interactionParticipantsFromForm("scheduled")
      .filter((participant) => participant.email || participant.phone).length;
    const alreadyRegistered = communicationsForInteraction(els.interactionForm.dataset.interactionId)
      .some((record) => record.automationType === "meeting_reminder"
        && record.automationKey?.includes(`:${els.interactionStartInput.value}:${reminder.offsetMinutes}:`));
    els.interactionReminderSummary.textContent = alreadyRegistered
      ? "Påminnelsen för den här mötestiden har registrerats."
      : !contactCount
        ? "Lägg till e-post eller telefon för minst en deltagare."
        : Number.isFinite(triggerAt) && triggerAt <= Date.now()
          ? `Påminnelsetiden (${meetingReminderOffsetLabel(reminder.offsetMinutes)} före) har passerat. Utskicket behandlas när mötet sparas.`
        : Number.isFinite(triggerAt)
          ? `Planerad ${formatDateTime(new Date(triggerAt).toISOString())} till ${contactCount} ${contactCount === 1 ? "deltagare" : "deltagare"}.`
          : "Ange mötets datum och tid.";
  } else {
    els.interactionReminderSummary.textContent = "Ingen automatisk påminnelse är planerad.";
  }
  els.interactionSendMessageButton.hidden = !existingInteraction || existingInteraction.kind !== "meeting";

  const caseRecord = cases.find((item) => item.id === els.interactionCaseInput.value);
  els.interactionCaseHelp.textContent = caseRecord
    ? `${caseRecord.number} · ${caseRecord.type}. Deltagare från ärendet har föreslagits.`
    : scheduled
      ? "Välj ett ärende när mötet ingår i handläggningen."
      : "Välj ett ärende när kontakten ingår i handläggningen.";
  if (!caseRecord || !applyCaseSuggestions) return;
  els.interactionParentInput.value = caseRecord.parentId || "";
  els.interactionMentorInput.value = caseRecord.mentorId || "";
  els.interactionOrganizerInput.value = responsibleHandler(caseRecord)?.id || CURRENT_USER_ID;
  els.interactionHandlerInput.value = responsibleHandler(caseRecord)?.id || "";
  if (scheduled && (!els.interactionTitleInput.value || els.interactionTitleInput.dataset.suggested === "true")) {
    els.interactionTitleInput.value = suggestedMeetingTitle(caseRecord);
    els.interactionTitleInput.dataset.suggested = "true";
  }
  renderInteractionParticipantStates();
}

function openInteractionForm(intent = "scheduled", caseId = "", interactionId = "", preferredActivityId = "") {
  const existing = interactions.find((item) => item.id === interactionId) || allInteractions().find((item) => item.id === interactionId);
  els.interactionForm.reset();
  clearInteractionValidity();
  els.interactionSubmitButton.disabled = false;
  els.interactionForm.dataset.interactionId = existing?.id || "";
  els.interactionForm.dataset.originalStatus = existing?.status || "";
  els.interactionForm.dataset.rescheduledFromInteractionId = "";
  els.interactionForm.dataset.activityId = existing?.activityId || preferredActivityId || "";
  setInteractionDraftItems("externalParticipants", []);
  setInteractionDraftItems("communicationHistory", existing?.communicationHistory || []);
  const resolvedIntent = existing?.status === "scheduled" ? "scheduled" : existing ? "completed" : intent;
  els.interactionScheduledInput.checked = resolvedIntent === "scheduled";
  els.interactionCompletedInput.checked = resolvedIntent === "completed";
  els.interactionCaseInput.innerHTML = '<option value="">Fristående möte</option>';
  for (const caseRecord of [...cases].filter((item) => item.status !== "closed" || [existing?.caseId, caseId].includes(item.id)).sort((left, right) => left.number.localeCompare(right.number, "sv"))) {
    const option = document.createElement("option");
    option.value = caseRecord.id;
    option.textContent = `${caseRecord.number} · ${caseRecord.type} · ${caseRecord.title}`;
    els.interactionCaseInput.append(option);
  }
  populateInteractionSelect(els.interactionParentInput, [...parents].sort((a, b) => a.name.localeCompare(b.name, "sv")), (parent) => `${parent.name}${parent.contactDetails ? ` · ${parent.contactDetails}` : ""}`);
  populateInteractionSelect(els.interactionMentorInput, [...candidates].filter((candidate) => candidate.active !== false).sort((a, b) => a.name.localeCompare(b.name, "sv")), (mentor) => `${mentor.name}${mentor.contactDetails ? ` · ${mentor.contactDetails}` : ""}`);
  const activeHandlers = [...handlers].filter((handler) => handler.active !== false);
  populateInteractionSelect(els.interactionOrganizerInput, activeHandlers, (handler) => `${handler.name}${handler.email ? ` · ${handler.email}` : ""}`, CURRENT_USER_ID);
  populateInteractionSelect(els.interactionHandlerInput, activeHandlers, (handler) => `${handler.name}${handler.email ? ` · ${handler.email}` : ""}`);
  els.interactionCaseInput.value = existing?.caseId || caseId || "";
  const startsAt = new Date();
  if (resolvedIntent === "scheduled") startsAt.setMinutes(Math.ceil(startsAt.getMinutes() / 15) * 15, 0, 0);
  els.interactionStartInput.value = localDateTimeValue(existing?.startsAt || startsAt);
  els.interactionEndInput.value = localDateTimeValue(existing?.endsAt || new Date(startsAt.getTime() + 60 * 60 * 1000));
  els.interactionTitleInput.value = existing?.title || (intent === "scheduled" ? "Möte" : "");
  els.interactionTitleInput.dataset.suggested = existing ? "false" : "true";
  els.interactionKindInput.value = existing?.kind || (intent === "scheduled" ? "meeting" : "phone");
  const outcomeInput = els.interactionForm.querySelector(`input[name="interactionOutcomeStatus"][value="${existing?.status || "completed"}"]`)
    || els.interactionForm.querySelector('input[name="interactionOutcomeStatus"][value="completed"]');
  if (outcomeInput) outcomeInput.checked = true;
  els.interactionModeInput.value = existing?.mode || "physical";
  els.interactionLocationInput.value = existing?.location || "";
  els.interactionInvitationInput.value = existing?.invitationText || "";
  const reminder = normalizeMeetingReminder(existing?.reminder || { enabled: !existing && resolvedIntent === "scheduled", offsetMinutes: 1440 });
  els.interactionReminderEnabledInput.checked = reminder.enabled;
  els.interactionReminderOffsetInput.value = String(reminder.offsetMinutes);
  els.interactionInvitationDetails.open = Boolean(reminder.enabled || existing?.invitationText || existing?.participants?.some((participant) => participant.responseStatus && participant.responseStatus !== "no_response"));
  els.interactionCommunicationDetails.open = Boolean(existing?.communicationHistory?.length || communicationsForInteraction(existing?.id).length);
  els.interactionCommunicationAtInput.value = localDateTimeValue();
  els.interactionCommunicationCommentInput.value = "";
  els.interactionCommunicationHelp.textContent = "Händelsen sparas tillsammans med mötet.";
  els.interactionSummaryInput.value = existing?.summary || "";
  els.interactionNextStepInput.value = existing?.nextStep || "";
  updateInteractionFormState({ applyCaseSuggestions: !existing });
  if (existing) {
    const participant = (partyType) => existing.participants.find((item) => item.partyType === partyType);
    els.interactionParentInput.value = participant("parent")?.partyId || "";
    els.interactionMentorInput.value = participant("mentor")?.partyId || "";
    els.interactionOrganizerInput.value = existing.organizerId || CURRENT_USER_ID;
    els.interactionHandlerInput.value = participant("handler")?.partyId || "";
    setInteractionDraftItems("externalParticipants", existing.participants.filter((item) => item.partyType === "external"));
    els.interactionForm.dataset.attendance = JSON.stringify(Object.fromEntries(existing.participants.map((item) => [item.id, item.attendanceStatus])));
    els.interactionForm.dataset.responses = JSON.stringify(Object.fromEntries(existing.participants.map((item) => [item.id, item.responseStatus])));
    renderInteractionParticipantStates();
  } else {
    els.interactionForm.dataset.attendance = "{}";
    els.interactionForm.dataset.responses = "{}";
    renderInteractionParticipantStates();
  }
  renderExternalParticipants();
  renderInteractionCommunicationHistory();
  renderInteractionSystemCommunications(existing?.id || "");
  updateInteractionFormState();
  els.interactionForm.dataset.dirty = "false";
  els.interactionForm.querySelector(".interaction-form-scroll").scrollTop = 0;
  bootstrap.Offcanvas.getOrCreateInstance(els.interactionOffcanvas).show();
  setTimeout(() => (caseId ? els.interactionTitleInput : els.interactionCaseInput).focus(), 150);
}

function selectedInteractionParticipants() {
  const participants = [];
  const parent = parents.find((item) => item.id === els.interactionParentInput.value);
  const mentor = candidates.find((item) => item.id === els.interactionMentorInput.value);
  const handler = handlers.find((item) => item.id === els.interactionHandlerInput.value);
  const contact = (record) => {
    const value = String(record?.contactDetails || record?.contact || "").trim();
    return value.includes("@") ? { email: value } : value ? { phone: value } : {};
  };
  if (parent) participants.push(interactionParticipant({ partyType: "parent", partyId: parent.id, displayName: parent.name, roleLabel: "Förälder", ...contact(parent) }));
  if (mentor) participants.push(interactionParticipant({ partyType: "mentor", partyId: mentor.id, displayName: mentor.name, roleLabel: "Mentor", ...contact(mentor) }));
  if (handler) participants.push(interactionParticipant({ partyType: "handler", partyId: handler.id, displayName: handler.name, roleLabel: handler.role || "Handläggare", email: handler.email || "" }));
  participants.push(...externalParticipantsFromForm());
  return participants;
}

function renderInteractionAttendance() {
  if (!els.interactionAttendanceFields) return;
  const previous = JSON.parse(els.interactionForm.dataset.attendance || "{}");
  const participants = selectedInteractionParticipants();
  els.interactionAttendanceFields.innerHTML = participants.length
    ? participants.map((participant) => `<label class="interaction-attendance-option"><span>${escapeHtml(participant.displayName)}</span><select class="form-select form-select-sm" data-interaction-attendance="${escapeHtml(participant.id)}"><option value="" ${!previous[participant.id] || previous[participant.id] === "not_recorded" ? "selected" : ""}>Ej registrerat</option><option value="attended" ${previous[participant.id] === "attended" ? "selected" : ""}>Närvarade</option><option value="did_not_attend" ${previous[participant.id] === "did_not_attend" ? "selected" : ""}>Frånvarande</option></select></label>`).join("")
    : '<span class="small text-secondary">Lägg till deltagare ovan för att registrera närvaro.</span>';
}

function renderInteractionResponses() {
  if (!els.interactionResponseFields) return;
  const previous = JSON.parse(els.interactionForm.dataset.responses || "{}");
  const participants = selectedInteractionParticipants();
  els.interactionResponseFields.innerHTML = participants.length
    ? participants.map((participant) => `<label class="interaction-response-option"><span>${escapeHtml(participant.displayName)}</span><select class="form-select form-select-sm" data-interaction-response="${escapeHtml(participant.id)}"><option value="no_response" ${previous[participant.id] === "no_response" || !previous[participant.id] ? "selected" : ""}>Inget svar</option><option value="accepted" ${previous[participant.id] === "accepted" ? "selected" : ""}>Tackat ja</option><option value="tentative" ${previous[participant.id] === "tentative" ? "selected" : ""}>Preliminärt</option><option value="declined" ${previous[participant.id] === "declined" ? "selected" : ""}>Tackat nej</option></select></label>`).join("")
    : '<span class="small text-secondary">Lägg till deltagare ovan för att registrera svar.</span>';
}

function renderInteractionParticipantStates() {
  renderInteractionAttendance();
  renderInteractionResponses();
}

function interactionParticipantsFromForm(status) {
  const participants = selectedInteractionParticipants();
  const attendance = new Map([...els.interactionAttendanceFields.querySelectorAll("[data-interaction-attendance]")]
    .map((input) => [input.dataset.interactionAttendance, input.value]));
  const responses = new Map([...els.interactionResponseFields.querySelectorAll("[data-interaction-response]")]
    .map((input) => [input.dataset.interactionResponse, input.value]));
  return participants.map((participant) => ({
    ...participant,
    invitationStatus: status === "scheduled" && els.interactionInvitationInput.value.trim() ? "prepared" : participant.invitationStatus,
    responseStatus: responses.get(participant.id) || participant.responseStatus,
    attendanceStatus: status === "completed" && els.interactionKindInput.value === "meeting"
      ? attendance.get(participant.id) || "not_recorded"
      : status === "completed" ? "attended" : status === "scheduled" ? participant.attendanceStatus : "not_recorded"
  }));
}

function rescheduleInteraction(interactionId) {
  const source = allInteractions().find((interaction) => interaction.id === interactionId);
  if (!source || !["cancelled", "no_show"].includes(source.status)) return;
  openInteractionForm("scheduled", source.caseId || "");
  els.interactionForm.dataset.rescheduledFromInteractionId = source.id;
  els.interactionTitleInput.value = source.title || "Möte";
  els.interactionTitleInput.dataset.suggested = "false";
  els.interactionModeInput.value = source.mode || "physical";
  els.interactionLocationInput.value = source.location || "";
  els.interactionInvitationInput.value = source.invitationText || "";
  els.interactionOrganizerInput.value = source.organizerId || CURRENT_USER_ID;
  const participant = (partyType) => source.participants.find((item) => item.partyType === partyType);
  els.interactionParentInput.value = participant("parent")?.partyId || els.interactionParentInput.value;
  els.interactionMentorInput.value = participant("mentor")?.partyId || els.interactionMentorInput.value;
  els.interactionHandlerInput.value = participant("handler")?.partyId || els.interactionHandlerInput.value;
  setInteractionDraftItems("externalParticipants", source.participants.filter((item) => item.partyType === "external"));
  setInteractionDraftItems("communicationHistory", []);
  els.interactionCaseHelp.textContent = `${els.interactionCaseHelp.textContent} En ny bokning skapas och den tidigare posten behålls.`;
  renderInteractionParticipantStates();
  renderExternalParticipants();
  renderInteractionCommunicationHistory();
}

function openInteractionForParty(partyType, partyId) {
  openInteractionForm("scheduled");
  if (partyType === "parent") els.interactionParentInput.value = partyId;
  if (partyType === "mentor") els.interactionMentorInput.value = partyId;
  renderInteractionParticipantStates();
}

function meetingActivityForCase(caseRecord) {
  const preferredTemplateIds = caseRecord?.caseTypeId === "mentor-certification"
    ? ["interviewDone"]
    : caseRecord?.caseTypeId === "matching"
      ? ["matchingFirstMeeting"]
      : [];
  return activitiesForCase(caseRecord?.id).find((activity) => preferredTemplateIds.includes(activity.templateId) && !["completed", "not_applicable"].includes(activity.status)) || null;
}

async function saveDirectInteraction(interaction) {
  const caseRecord = cases.find((item) => item.id === interaction.caseId);
  if (!caseRecord) {
    await saveInteraction(interaction);
    return;
  }
  const now = interaction.updatedAt;
  const updatedCase = { ...caseRecord, version: caseRecord.version + 1, updatedAt: now, updatedBy: CURRENT_USER_ID };
  await atomicPut({
    [INTERACTIONS_STORE]: [interaction],
    [CASES_STORE]: [updatedCase],
    [CASE_EVENTS_STORE]: [caseEventRecord({
      caseId: caseRecord.id,
      eventType: "interaction_registered",
      entityType: "interaction",
      entityId: interaction.id,
      message: `${INTERACTION_KIND_LABELS[interaction.kind] || "Kontakt"} registrerades: ${interaction.title}`,
      idempotencyKey: crypto.randomUUID(), correlationId: crypto.randomUUID(), now
    })]
  });
}

