function moveToCurrentLearningModule() {
  if (parseRoute().params.get("mode") !== "focus") return;
  requestAnimationFrame(() => requestAnimationFrame(() => {
    const target = document.querySelector(".learning-module.is-next[aria-current='step']") || document.querySelector(".learning-course-completion") || document.querySelector(".learning-focus-current");
    target?.scrollIntoView({ behavior: "smooth", block: "start" });
    target?.querySelector("summary")?.focus({ preventScroll: true });
  }));
}

function updateLearningReflectionValidation(textarea, { report = false } = {}) {
  const assessment = assessLearningReflection(textarea.value);
  const form = textarea.closest("[data-learning-reflection]");
  const help = form?.querySelector("[data-learning-reflection-help]");
  const message = form?.querySelector("[data-learning-reflection-message]");
  const status = form?.querySelector("[data-learning-reflection-status]");
  if (report && !assessment.valid && form) form.dataset.validationAttempted = "true";
  const attempted = form?.dataset.validationAttempted === "true";
  const feedback = learningReflectionFeedback(assessment, textarea.value, attempted);
  textarea.setCustomValidity(assessment.valid ? "" : feedback.message);
  help?.classList.toggle("is-valid", assessment.valid);
  help?.classList.toggle("is-invalid", !assessment.valid && attempted);
  if (message) message.textContent = feedback.message;
  if (status) {
    status.textContent = feedback.status;
    status.hidden = !feedback.status;
  }
  if (report && !assessment.valid) {
    textarea.reportValidity();
    textarea.focus();
  }
  return assessment.valid;
}

els.learningView.addEventListener("input", (event) => {
  const textarea = event.target.closest("[data-learning-reflection] textarea");
  if (textarea) updateLearningReflectionValidation(textarea);
});

els.learningView.addEventListener("click", async (event) => {
  const focusButton = event.target.closest("[data-focus-learning-module]");
  if (focusButton) {
    const moduleElement = document.getElementById(`learning-module-${focusButton.dataset.focusLearningModule}`);
    if (moduleElement) {
      moduleElement.open = true;
      moduleElement.scrollIntoView({ behavior: "smooth", block: "start" });
      moduleElement.querySelector("summary")?.focus({ preventScroll: true });
    }
    return;
  }
  const filterButton = event.target.closest("[data-learning-filter]");
  if (filterButton) {
    learningTypeFilter = filterButton.dataset.learningFilter;
    renderLearning();
    return;
  }
  const completeButton = event.target.closest("[data-complete-learning-module]");
  if (!completeButton || !selectedLearnerId) return;
  completeButton.disabled = true;
  const courseId = completeButton.dataset.courseId;
  const moduleId = completeButton.dataset.completeLearningModule;
  await queueLearningMutation(() => completeLearningModule(courseId, moduleId));
  showFeedback("Kursmomentet har markerats som klart.");
  moveToCurrentLearningModule();
});

els.learningView.addEventListener("submit", async (event) => {
  const reflectionForm = event.target.closest("[data-learning-reflection]");
  if (reflectionForm) {
    event.preventDefault();
    const courseId = reflectionForm.dataset.courseId;
    const moduleId = reflectionForm.dataset.learningReflection;
    const textarea = reflectionForm.querySelector("textarea");
    if (!updateLearningReflectionValidation(textarea, { report: true })) return;
    const reflection = textarea.value.trim();
    reflectionForm.querySelector('button[type="submit"]').disabled = true;
    await queueLearningMutation(() => {
      const record = learningProgressRecord(selectedLearnerId, courseId);
      return completeLearningModule(courseId, moduleId, {
        reflections: { ...(record.reflections || {}), [moduleId]: reflection }
      });
    });
    showFeedback("Reflektionen har sparats.");
    moveToCurrentLearningModule();
    return;
  }
  const testForm = event.target.closest("[data-learning-test]");
  if (!testForm) return;
  event.preventDefault();
  const test = learningContentById(selectedLearningContent(), testForm.dataset.learningTest);
  if (!test || !selectedLearnerId) return;
  testForm.querySelector('button[type="submit"]').disabled = true;
  const answers = Object.fromEntries(test.questions.map((question) => [question.id, new FormData(testForm).get(question.id)]));
  const result = scoreKnowledgeTest(test, answers);
  const courseId = testForm.dataset.courseId || `test:${test.id}`;
  const moduleId = testForm.dataset.moduleId;
  await queueLearningMutation(async () => {
    const record = learningProgressRecord(selectedLearnerId, courseId);
    const completedModuleIds = result.passed ? [...new Set([...(record.completedModuleIds || []), moduleId])] : record.completedModuleIds || [];
    const attemptedAt = new Date().toISOString();
    await saveLearningProgress(learningProgressWithTimestamps(record, courseId, completedModuleIds, {
      attempts: [...(record.attempts || []), { testId: test.id, testVersion: test.version, answers, ...result, attemptedAt }]
    }, attemptedAt));
    markSaved();
    await refresh();
  });
  showFeedback(result.passed ? `Testet är godkänt med ${result.score}%.` : `Resultatet blev ${result.score}%. Testet behöver göras om.`);
  if (result.passed) moveToCurrentLearningModule();
});

